// Compile lead data and conversation history
const lead = $('New HOT Lead').item.json;
const conversations = $input.all();

// Format conversation history
const conversationHistory = conversations.map(c => {
  const fields = c.json.fields || {};
  return `[${fields.Timestamp || 'Unknown'}] ${fields.Direction || ''} ${fields.Type || ''}: ${fields.Body || fields.Subject || 'No content'}`;
}).join('\n\n');

// Parse AI Analysis if available
let aiAnalysis = {};
try {
  if (lead.fields['AI Analysis']) {
    aiAnalysis = JSON.parse(lead.fields['AI Analysis']);
  }
} catch (e) {}

return [{
  json: {
    lead: lead,
    conversationHistory: conversationHistory || 'No prior conversations',
    aiAnalysis: aiAnalysis,
    conversationCount: conversations.length
  }
}];

